    "city": "Hyderabad",
    "state": "Telangana",
    "latitude": 17.3482689932249,
    "longitude": 78.5325166807634,
    "timings": "01pm to 3pm",
    "description": "🕉️ Ganesh Chaturthi – 23rd Year Celebrations 🙏\n\nFor the past 23 years, BNCFA – Bhagya Nagar Colony Friends Association, Team BHEEMA, has come together to celebrate Ganesh Chaturthi with the same spirit of devotion, friendship, unity, and community.\n\n\nEvery year, our pandal remains at the same location, while the celebration brings a new style, a new theme, and a different traditional form of Lord Ganesha. What makes these celebrations truly special is not just the idol or the festivities, but the bond of friendship and togetherness — connecting those who are with us today and those who are away but remain a part of these memories and traditions.\n\n\n\n🌺 This Year – Don’t Miss the Celebrations!\n\n📍 Bhagya Nagar Colony Friends Association – Team BHEEMA\n🎊 23rd Year Celebrations\n🕉️ Traditional Ganesh Celebrations\n🍬 Laddu Auction\n🎁 Lucky Draw Laddu\n🙏 Family & Community Celebrations\n\n\n\n🪔 Ganesh Immersion\n\n📅 26th September 2026\n⏰ 3:00 PM Afternoon\n\n\n\nWe warmly invite everyone to join us with your family and friends and become a part of another beautiful year of devotion, friendship, and unforgettable memories.\n\n\n\n🤝 With the Support of Our Brothers & Community\n\n\n\nCore pillar Members:- \n\nSaideep Honali • Maharshi Vishwakarma • Rohit Goud • Ashwin Kumar Madishetty • Sai Kiran Pasnoor • Bala Gangadhar Diddi • Hemant Kumar • Karthik Rao • Sheshank Goud • Dhruva Star • Akhil Yadav • Abhinav Yadav • Vasant Amarai • Harish Yadav • Rahul Yadav • Pradeep Goud • Pranay • Yeshwanth Reddy • Munna – Mahidhar • Mukesh Reddy • Ankishetty Vinod.\n\n\n\nWith the Support of Our Brothers:-\n\nAshish Goud • Prashant Surineni • Satish Merry • Rama Raju Birrey.\n\n\n\nAnd with the continued support of our Colony President Raju Yadav, colony members, families, friends, and everyone who has stood together with us throughout these 23 years.\n\n\n\n🕉️ 23 Years. Same Place. New Ganesh. New Memories.\n\n\n\n🙏 The tradition continues. The friendships remain. ❤️\n\n\n\n॥ श्री गणेशाय नमः ॥\n॥ गणपति बप्पा मोरया ॥\n॥ मं",
    "image": "https://hxmkkloyoyfjpxyfdoxc.supabase.co/storage/v1/object/public/uploads/pandals/4791f12d-a3a2-428f-a3f0-c843aedd4351.jpg",
